export default "import {\n  behaviors,\n  EmbeddedScene,\n  PanelBuilders,\n  SceneAppPage,\n  SceneAppPageState,\n  SceneFlexItem,\n  SceneFlexLayout,\n  VizPanel,\n} from '@grafana/scenes';\nimport { DashboardCursorSync } from '@grafana/schema';\nimport { demoUrl } from '../utils/utils.routing';\nimport { getEmbeddedSceneDefaults, getQueryRunnerWithRandomWalkQuery } from './utils';\n\nexport function global() {\n  return new SceneAppPage({\n    title: 'Global sync scope',\n    url: demoUrl('cursor-sync'),\n    routePath: 'cursor-sync/*',\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        key: 'Flex layout embedded scene',\n        $behaviors: [new behaviors.CursorSync({ key: 'sync1', sync: DashboardCursorSync.Tooltip })],\n        body: new SceneFlexLayout({\n          direction: 'column',\n          children: [\n            new SceneFlexLayout({\n              direction: 'row',\n              children: [\n                new SceneFlexItem({\n                  body: new VizPanel({\n                    title: 'Panel 1',\n                    pluginId: 'timeseries',\n                    $data: getQueryRunnerWithRandomWalkQuery({\n                      scenarioId: 'csv_metric_values',\n                      stringInput: '1,20,90,30,5,0',\n                    }),\n                  }),\n                }),\n                new SceneFlexItem({\n                  body: PanelBuilders.timeseries()\n                    .setData(\n                      getQueryRunnerWithRandomWalkQuery(\n                        {\n                          scenarioId: 'csv_metric_values',\n                          stringInput: '1,20,90,30,5,0',\n                        },\n                        { maxDataPoints: 50 }\n                      )\n                    )\n                    .setTitle('Panel 2')\n                    .build(),\n                }),\n              ],\n            }),\n            new SceneFlexLayout({\n              direction: 'row',\n              children: [\n                new SceneFlexItem({\n                  body: new VizPanel({\n                    title: 'Panel 3',\n                    pluginId: 'timeseries',\n                    $data: getQueryRunnerWithRandomWalkQuery({}),\n                  }),\n                }),\n              ],\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\nexport function scoped() {\n  return new SceneAppPage({\n    title: 'Cursor sync test',\n    url: demoUrl('cursor-sync/scoped'),\n    routePath: 'scoped',\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        key: 'Flex layout embedded scene',\n        body: new SceneFlexLayout({\n          direction: 'column',\n          children: [\n            new SceneFlexLayout({\n              direction: 'row',\n              $behaviors: [new behaviors.CursorSync({ key: 'sync1', sync: DashboardCursorSync.Tooltip })],\n              children: [\n                new SceneFlexItem({\n                  body: new VizPanel({\n                    title: 'Panel 1 - syncs tooltip with Panel 2',\n                    pluginId: 'piechart',\n                    $data: getQueryRunnerWithRandomWalkQuery({\n                      alias: '__house_locations',\n                      seriesCount: 5,\n                      scenarioId: 'random_walk',\n                    }),\n                  }),\n                }),\n                new SceneFlexItem({\n                  body: PanelBuilders.piechart()\n                    .setData(\n                      getQueryRunnerWithRandomWalkQuery(\n                        {\n                          alias: '__house_locations',\n                          seriesCount: 5,\n                          scenarioId: 'random_walk',\n                        },\n                        { maxDataPoints: 50 }\n                      )\n                    )\n                    .setTitle('Panel 2')\n                    .build(),\n                }),\n              ],\n            }),\n            new SceneFlexLayout({\n              direction: 'row',\n              $behaviors: [new behaviors.CursorSync({ key: 'sync1', sync: DashboardCursorSync.Tooltip })],\n              children: [\n                new SceneFlexItem({\n                  body: new VizPanel({\n                    title: 'Panel 1 - syncs tooltip with Panel 2',\n                    pluginId: 'timeseries',\n                    $data: getQueryRunnerWithRandomWalkQuery({\n                      scenarioId: 'csv_metric_values',\n                      stringInput: '1,20,90,30,5,0',\n                    }),\n                  }),\n                }),\n                new SceneFlexItem({\n                  body: PanelBuilders.timeseries()\n                    .setData(\n                      getQueryRunnerWithRandomWalkQuery(\n                        {\n                          scenarioId: 'csv_metric_values',\n                          stringInput: '1,20,90,30,5,0',\n                        },\n                        { maxDataPoints: 50 }\n                      )\n                    )\n                    .setTitle('Panel 2')\n                    .build(),\n                }),\n              ],\n            }),\n            new SceneFlexLayout({\n              direction: 'row',\n              $behaviors: [new behaviors.CursorSync({ key: 'sync2', sync: DashboardCursorSync.Crosshair })],\n              children: [\n                new SceneFlexItem({\n                  body: new VizPanel({\n                    title: 'Panel 3 - syncs crosshair with Panel 4',\n                    pluginId: 'timeseries',\n                    $data: getQueryRunnerWithRandomWalkQuery({}),\n                  }),\n                }),\n                new SceneFlexItem({\n                  body: PanelBuilders.timeseries()\n                    .setData(getQueryRunnerWithRandomWalkQuery({}, { maxDataPoints: 50 }))\n                    .setTitle('Panel 4')\n                    .build(),\n                }),\n              ],\n            }),\n            new SceneFlexLayout({\n              direction: 'row',\n              $behaviors: [new behaviors.CursorSync({ key: 'sync3', sync: DashboardCursorSync.Off })],\n              children: [\n                new SceneFlexItem({\n                  body: new VizPanel({\n                    title: 'No sync',\n                    pluginId: 'timeseries',\n                    $data: getQueryRunnerWithRandomWalkQuery({}),\n                  }),\n                }),\n                new SceneFlexItem({\n                  body: PanelBuilders.timeseries()\n                    .setData(getQueryRunnerWithRandomWalkQuery({}, { maxDataPoints: 50 }))\n                    .setTitle('No sync')\n                    .build(),\n                }),\n              ],\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n\nexport function getCursorSyncTest(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    url: demoUrl('cursor-sync'),\n    tabs: [global(), scoped()],\n  });\n}\n";